/* Familiar chart workflows, original Eero design. Sample records only. */
for(const [view,title] of [['chart','Chart navigator'],['careplans','Care plans']]){const b=document.createElement('button');b.dataset.view=view;b.innerHTML=icon('review')+`<span>${title}</span>`;b.onclick=()=>{currentView=view;render()};document.querySelector('nav').append(b);labels[view]=title}
let selectedChartCase,selectedChartTab='overview';const chartPanel=document.createElement('section');chartPanel.id='chart-panel';chartPanel.hidden=true;document.querySelector('footer').before(chartPanel);
function getChart(){state.charts??={};const id=selectedChartCase||state.cases[0]?.id;if(!id)return null;selectedChartCase=id;state.charts[id]??={medications:[],allergies:[],goals:[],history:'Not documented in this sample chart.',encounters:[]};return state.charts[id]}
function chartHTML(){const chart=getChart(),c=state.cases.find(x=>x.id===selectedChartCase);if(!chart||!c)return '<div class="empty">Create a sample case to open the chart navigator.</div>';let body='';const docs=state.docs.filter(d=>d.caseId===c.id),pending=docs.filter(d=>d.status==='Needs review').length;chart.observations??=[];const tabs=['overview','observations','medications','allergies','encounters','history'];if(currentView==='careplans')body=`<div class="panel-heading"><div><h2>Goals that guide the work.</h2><p>Clinician-entered sample goals. No automatic treatment recommendations.</p></div><button class="primary" id="goal-add">＋ Goal</button></div><div class="goal-list">${chart.goals.map(g=>`<article class="goal-card"><span class="age-tag">${esc(g.status)}</span><h3>${esc(g.title)}</h3><p>${esc(g.measure)}</p><small>Target ${esc(g.target)}</small><label class="field">Update progress<select data-goal="${esc(g.id)}"><option ${g.status==='Planned'?'selected':''}>Planned</option><option ${g.status==='In progress'?'selected':''}>In progress</option><option ${g.status==='Achieved'?'selected':''}>Achieved</option></select></label></article>`).join('')||'<div class="empty">No goals documented. Add a sample goal and a way to measure progress.</div>'}</div>`;else{if(selectedChartTab==='overview')body=`<div class="chart-overview"><article><span class="tiny-label">REVIEW CHECKLIST</span><h3>Prepare for the encounter.</h3><p>${pending} documents need review.</p><p>Medication history: ${chart.medications.length?'Entries need clinician review.':'Not documented.'}</p><p>Allergy history: ${chart.allergies.length?'Entries need clinician review.':'Unknown / not reviewed. This does not mean no allergies.'}</p><p>Care-plan goals: ${chart.goals.length} documented.</p><button class="secondary" data-chart-view="careplans">Open care plan ↗</button></article><article><span class="tiny-label">DOCUMENT NAVIGATOR</span>${docs.map(d=>`<button class="profile-doc" data-chart-doc="${esc(d.id)}">${icon('review')}<span>${esc(d.title)}</span><span class="badge ${d.status==='Approved'?'approved':''}">${esc(d.status)}</span></button>`).join('')||'<p class="muted">No documents yet.</p>'}</article></div>`;if(selectedChartTab==='medications'||selectedChartTab==='allergies'){const kind=selectedChartTab;body=`<div class="panel-heading"><div><h2>${kind==='medications'?'Reported medications':'Reported allergies'}</h2><p>Reported information only. These entries are unverified; no reconciliation or prescribing occurs.</p></div><button class="primary" id="chart-item-add">＋ Add entry</button></div>${chart[kind].map(x=>`<div class="case-row"><div class="row-info"><strong>${esc(x.name)}</strong><small>${esc(x.details)} · Source: ${esc(x.source)}</small></div><span class="badge">Unverified</span></div>`).join('')||`<div class="empty">${kind==='allergies'?'Allergy status unknown / not reviewed.':'Medication history not documented.'}</div>`}`};if(selectedChartTab==='encounters')body=`<div class="panel-heading"><div><h2>Encounter workspace</h2><p>Sample service encounters and draft notes.</p></div><button class="primary" id="encounter-add">＋ Encounter</button></div>${chart.encounters.map(e=>`<div class="case-row"><div class="row-info"><strong>${esc(e.service)}</strong><small>${esc(e.date)} · ${esc(e.location)} · Draft</small></div><button class="secondary" data-encounter-note="${esc(e.id)}">Write note</button></div>`).join('')||'<div class="empty">No sample encounters documented.</div>'}`;if(selectedChartTab==='observations')body=observationHTML(chart);if(selectedChartTab==='history')body=`<h2>Background and context</h2><p class="muted">Manual sample documentation. Keep client statements separate from clinician interpretation.</p><textarea id="chart-history" style="min-height:180px">${esc(chart.history)}</textarea><div class="modal-actions"><button class="primary" id="chart-history-save">Save sample history</button></div>`}
return `<div class="chart-top"><div><span class="tiny-label">EERO / CLINICAL WORKSPACE</span><h2>${esc(c.label)}</h2><p>${esc(c.service)} · Sample chart · Status: unverified</p></div><label class="field">Case<select id="chart-case-select">${caseOptions()}</select></label></div>${currentView==='chart'?`<div class="chart-tabs">${tabs.map(t=>`<button data-chart-tab="${t}" class="${selectedChartTab===t?'active':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div>`:''}<div class="chart-body">${body}</div>`}
const itemDialog=newDialog('chart-item-dialog','<form id="chart-item-form"><div class="modal-heading"><h2 id="chart-item-title">Add reported entry</h2><button type="button" class="close" aria-label="Close">×</button></div><label class="field">Name<input id="chart-item-name" required maxlength="150"></label><label class="field">Reported details<textarea id="chart-item-details" required maxlength="2000"></textarea></label><label class="field">Source<select id="chart-item-source"><option>Client report</option><option>Caregiver report</option><option>Referral document</option></select></label><p class="muted">This saves an unverified sample entry. It does not validate a medication, dose, allergy, or reaction.</p><div class="modal-actions"><button class="primary">Save reported entry</button></div></form>');
$('chart-item-form').onsubmit=async e=>{e.preventDefault();if(!$('chart-item-name').value.trim())return;getChart()[selectedChartTab].push({id:uid(),name:$('chart-item-name').value.trim(),details:$('chart-item-details').value,source:$('chart-item-source').value,status:'unverified'});await persist();itemDialog.close()};
const goalDialog=newDialog('goal-dialog','<form id="goal-form"><div class="modal-heading"><h2>Create a care-plan goal</h2><button type="button" class="close" aria-label="Close">×</button></div><label class="field">Goal<input id="goal-title" required maxlength="200"></label><label class="field">How will progress be measured?<textarea id="goal-measure" required maxlength="2000"></textarea></label><label class="field">Target date<input id="goal-target" type="date" required></label><div class="modal-actions"><button class="primary">Save sample goal</button></div></form>');$('goal-form').onsubmit=async e=>{e.preventDefault();if(!$('goal-title').value.trim())return;getChart().goals.push({id:uid(),title:$('goal-title').value.trim(),measure:$('goal-measure').value,target:$('goal-target').value,status:'Planned'});await persist();goalDialog.close()};
const encounterDialog=newDialog('encounter-dialog','<form id="encounter-form"><div class="modal-heading"><h2>Create sample encounter</h2><button type="button" class="close" aria-label="Close">×</button></div><label class="field">Service<input id="encounter-service" required maxlength="100"></label><label class="field">Date<input id="encounter-date" type="date" required></label><label class="field">Location<select id="encounter-location"><option>In community</option><option>In home</option><option>Office</option><option>Virtual</option></select></label><div class="modal-actions"><button class="primary">Save encounter</button></div></form>');$('encounter-form').onsubmit=async e=>{e.preventDefault();getChart().encounters.push({id:uid(),service:$('encounter-service').value,date:$('encounter-date').value,location:$('encounter-location').value});await persist();encounterDialog.close()};
chartPanel.onclick=e=>{const tab=e.target.closest('[data-chart-tab]'),doc=e.target.closest('[data-chart-doc]'),view=e.target.closest('[data-chart-view]'),note=e.target.closest('[data-encounter-note]');if(tab){selectedChartTab=tab.dataset.chartTab;render()}if(doc)openDoc(doc.dataset.chartDoc);if(view){currentView=view.dataset.chartView;render()}if(note){const enc=getChart().encounters.find(x=>x.id===note.dataset.encounterNote);$('digital-open').click();$('digital-case').value=selectedChartCase;$('digital-date').value=enc.date;$('digital-summary').value=`Sample encounter: ${enc.service} at ${enc.location}.\n`;linkedEncounter=enc.id}};chartPanel.onchange=async e=>{if(e.target.dataset.goal){getChart().goals.find(g=>g.id===e.target.dataset.goal).status=e.target.value;await persist()}};
const templateLabel=document.createElement('label');templateLabel.className='field';templateLabel.innerHTML='Note template<select id="note-template"><option value="general">General service note</option><option value="soap">SOAP</option><option value="dap">DAP</option></select>';$('digital-summary').closest('.field').before(templateLabel);const assessmentLabel=document.createElement('label');assessmentLabel.className='field';assessmentLabel.hidden=true;assessmentLabel.innerHTML='Assessment<textarea id="note-extra-assessment" maxlength="4000"></textarea>';$('digital-actions').closest('.field').after(assessmentLabel);let linkedEncounter=null;
function setNoteLabels(){const t=$('note-template').value,labels=t==='soap'?['Subjective','Objective','Plan']:t==='dap'?['Data','Assessment','Plan']:['Session summary','Actions taken','Next steps'];for(const [i,id] of ['digital-summary','digital-actions','digital-next'].entries())$(id).closest('.field').childNodes[0].textContent=labels[i];assessmentLabel.hidden=t!=='soap';$('note-extra-assessment').required=t==='soap'}$('note-template').onchange=setNoteLabels;const oldDigitalOpen=$('digital-open').onclick;$('digital-open').onclick=()=>{oldDigitalOpen();linkedEncounter=null;setNoteLabels()};
$('digital-form').onsubmit=async e=>{e.preventDefault();const t=$('note-template').value,note=t==='soap'?`SUBJECTIVE\n${$('digital-summary').value}\n\nOBJECTIVE\n${$('digital-actions').value}\n\nASSESSMENT\n${$('note-extra-assessment').value}\n\nPLAN\n${$('digital-next').value}`:t==='dap'?`DATA\n${$('digital-summary').value}\n\nASSESSMENT\n${$('digital-actions').value}\n\nPLAN\n${$('digital-next').value}`:`SESSION SUMMARY\n${$('digital-summary').value}\n\nACTIONS TAKEN\n${$('digital-actions').value}\n\nNEXT STEPS\n${$('digital-next').value}`;state.docs.push({id:uid(),caseId:$('digital-case').value,title:`${t==='general'?'Service':t.toUpperCase()} note · ${$('digital-date').value}`,type:'Service note',date:$('digital-date').value,notes:note,status:'Needs review',encounterId:linkedEncounter,events:[`Clinician-entered sample draft created ${new Date().toLocaleString()}`]});await persist();$('digital-modal').close();currentView='review';render();toast('Sample note saved for review. No signature or clinical approval applied.')};
const preClinicalRender=render;render=function(){const desired=currentView,special=['chart','careplans'].includes(desired);if(special)currentView='overview';preClinicalRender();currentView=desired;chartPanel.hidden=!special||portalRole==='client';if(special&&portalRole!=='client'){for(const selector of ['.hero','.stats','.quick-actions','.panel'])document.querySelector(selector).hidden=true;for(const id of ['home-extras','extra-panel','programs-panel','portal-panel'])$(id).hidden=true;chartPanel.innerHTML=chartHTML();$('page-title').textContent=labels[desired];if($('chart-case-select')){$('chart-case-select').value=selectedChartCase;$('chart-case-select').onchange=e=>{selectedChartCase=e.target.value;render()}}if($('chart-item-add'))$('chart-item-add').onclick=()=>{$('chart-item-form').reset();$('chart-item-title').textContent=selectedChartTab==='medications'?'Add reported medication':'Add reported allergy';itemDialog.showModal()};if($('goal-add'))$('goal-add').onclick=()=>{$('goal-form').reset();$('goal-target').value=today();goalDialog.showModal()};if($('encounter-add'))$('encounter-add').onclick=()=>{$('encounter-form').reset();$('encounter-date').value=today();encounterDialog.showModal()};if($('observation-add'))$('observation-add').onclick=()=>{$('observation-form').reset();$('observation-date').value=today();observationDialog.showModal()};if($('chart-history-save'))$('chart-history-save').onclick=async()=>{getChart().history=$('chart-history').value;await persist();toast('Sample history saved.')}}document.querySelectorAll('nav button').forEach(b=>{if(['chart','careplans'].includes(b.dataset.view))b.hidden=false;b.classList.toggle('active',b.dataset.view===desired)});};

function observationHTML(chart){return `<div class="panel-heading"><div><h2>Observation flowsheet</h2><p>Dated, manually entered sample observations. No diagnostic scoring.</p></div><button class="primary" id="observation-add">＋ Observation</button></div><div class="observation-table"><table><thead><tr><th>Date</th><th>Area</th><th>Observation</th><th>Source</th></tr></thead><tbody>${[...chart.observations].sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<tr><td>${esc(x.date)}</td><td>${esc(x.area)}</td><td>${esc(x.details)}</td><td>${esc(x.source)}<small>Unverified</small></td></tr>`).join('')||'<tr><td colspan="4">No observations recorded for this sample case.</td></tr>'}</tbody></table></div>`}
const observationDialog=newDialog('observation-dialog','<form id="observation-form"><div class="modal-heading"><h2>Add sample observation</h2><button type="button" class="close" aria-label="Close">×</button></div><label class="field">Date<input id="observation-date" type="date" required></label><label class="field">Area<select id="observation-area"><option>Session participation</option><option>Client-reported sleep</option><option>Client-reported wellbeing</option><option>Caregiver update</option><option>Other</option></select></label><label class="field">Observation<textarea id="observation-details" required maxlength="2000"></textarea></label><label class="field">Source<select id="observation-source"><option>Clinician observation</option><option>Client report</option><option>Caregiver report</option></select></label><p class="muted">Use fictional details. This log is not a validated assessment or safety-monitoring system.</p><div class="modal-actions"><button class="primary">Save sample observation</button></div></form>');$('observation-form').onsubmit=async e=>{e.preventDefault();const chart=getChart();chart.observations??=[];chart.observations.push({id:uid(),date:$('observation-date').value,area:$('observation-area').value,details:$('observation-details').value,source:$('observation-source').value});await persist();observationDialog.close()};

if(state)render();
